          analysis: '塔牌准确地描绘了他的一生：他就是一座不停地被雷劈的塔。每一次他以为生活可以稳定下来了，塔就倒一次——赌博输光家产是第一次，父亲去世是第二次，被抓壮丁是第三次，儿子去世是第四次，女儿去世是第五次，妻子去世是第六次，女婿去世是第七次，外孙去世是第八次。每一次崩塌都让他失去一部分自己，但他每一次都从废墟中爬起来，不是因为坚强，而是因为"不爬起来还能怎样呢？"'
